};

/**
 * Renders the current app plus the unprocessed ink into one PNG. Existing
 * components are drawn as labeled boxes so the model can aim wiring arrows at
 * exact component ids instead of guessing at them.
 */
const captureCanvasImage = useCallback(async (): Promise<string> => {
  const width = Math.round(canvasSize.width);
  const height = Math.round(canvasSize.height);
  const scale = Math.min(2, 2048 / Math.max(width, height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(width * scale);
  canvas.height = Math.round(height * scale);
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Could not create drawing snapshot");
  context.scale(scale, scale);
  context.fillStyle = "#f7f6f2";
  context.fillRect(0, 0, width, height);

  context.strokeStyle = "#8d8579";
  context.fillStyle = "#3b3730";
  context.lineWidth = 1.5;
  context.font = "600 13px -apple-system, BlinkMacSystemFont, sans-serif";
  for (const component of graphRef.current.components) {
    const { x, y, width: w, height: h } = component.bounds;
    context.strokeRect(x, y, w, h);
    context.fillText(
      `${component.id} · ${component.type} · ${componentLabel(component)}`,
      x + 6,
      y + Math.min(18, h / 2 + 5),
    );
  }

  context.lineCap = "round";
  context.lineJoin = "round";
  context.strokeStyle = "#171614";
  for (const stroke of strokesRef.current.filter(
    (candidate) => !candidate.processed,
  )) {
    if (stroke.points.length < 2) continue;
    context.beginPath();
    context.moveTo(stroke.points[0].x, stroke.points[0].y);
    for (const point of stroke.points.slice(1)) {
      context.lineTo(point.x, point.y);
    }
    const averagePressure =
      stroke.points.reduce((sum, point) => sum + point.pressure, 0) /
      stroke.points.length;
    context.lineWidth = 1.4 + averagePressure * 2.8;
    context.stroke();
  }

  return canvas.toDataURL("image/png");
}, [canvasSize]);

/**
 * Offline recognizer. Closed shapes become components; long strokes that start
 * and end on known components become behaviors.
 */
const localResponse = useCallback((pending: InkStroke[]): ProcessResponse => {
  const existing = graphRef.current.components;
  const components: AgentComponent[] = pending
    .filter(isClosedShape)
    .filter(
      (stroke) =>
        !existing.some((component) => hitTest(stroke.points[0], component, 0)),
    )
    .map((stroke, index) => {
      const bounds = getStrokeBounds(stroke);
      const type = guessComponentType(bounds);
      const props = defaultProps(type);
      return {
        id: `sketch-${existing.length + index + 1}`,
        type,
        x: bounds.x,
        y: bounds.y,
        width: bounds.width,
        height: bounds.height,
        label: props.label,
        placeholder: props.placeholder,
        dataSource: type === "List" ? "tasks" : "",
        stateKey: "",
        confidence: 0.58,
      };
    });

  const edges: AgentEdge[] = [];
  for (const stroke of pending) {
    if (stroke.points.length < 2 || strokeLength(stroke) < 70) continue;
    const start = stroke.points[0];
    const end = stroke.points[stroke.points.length - 1];
    const source = existing.find((component) => hitTest(start, component, 34));
    const target = existing.find(
      (component) =>
        component.id !== source?.id && hitTest(end, component, 34),
    );
    if (!source || !target) continue;
    const compiled = localHandler(source, target);
    edges.push({
      id: createId("edge"),
      source: source.id,
      target: target.id,
      ...compiled,
    });
  }

