          id: `sketch-${existing.length + index + 1}`,
          type,
          x: bounds.x,
          y: bounds.y,
          width: bounds.width,
          height: bounds.height,
          label: props.label,
          placeholder: props.placeholder,
          dataSource: type === "List" ? "tasks" : "",
          stateKey: "",
          confidence: 0.58,
        };
      });

    const edges: AgentEdge[] = [];
    for (const stroke of pending) {
      if (stroke.points.length < 2 || strokeLength(stroke) < 70) continue;
      const start = stroke.points[0];
      const end = stroke.points[stroke.points.length - 1];
      const source = existing.find((component) => hitTest(start, component, 34));
      const target = existing.find(
        (component) =>
          component.id !== source?.id && hitTest(end, component, 34),
      );
      if (!source || !target) continue;
      const compiled = localHandler(source, target);
      edges.push({
        id: createId("edge"),
        source: source.id,
        target: target.id,
        ...compiled,
      });
    }
