import { deflateSync } from "node:zlib";
import { writeFileSync } from "node:fs";

const W = 1024;
const H = 768;
const px = Buffer.alloc(W * H * 3, 0xf7); // paper-ish background

const set = (x, y, c = 17) => {
  if (x < 0 || y < 0 || x >= W || y >= H) return;
  const i = (y * W + x) * 3;
  px[i] = px[i + 1] = px[i + 2] = c;
};
const rect = (x1, y1, x2, y2, thick = 2) => {
  for (let x = x1; x <= x2; x++)
    for (let t = 0; t < thick; t++) {
      set(x, y1 + t);
      set(x, y2 - t);
    }
  for (let y = y1; y <= y2; y++)
    for (let t = 0; t < thick; t++) {
      set(x1 + t, y);
      set(x2 - t, y);
    }
};
const hline = (x1, x2, y, thick = 2) => {
  for (let x = x1; x <= x2; x++)
    for (let t = 0; t < thick; t++) set(x, y + t);
};
const vline = (y1, y2, x, thick = 2) => {
  for (let y = y1; y <= y2; y++)
    for (let t = 0; t < thick; t++) set(x + t, y);
};

// Display box
rect(380, 60, 640, 130);
hline(420, 600, 95, 3); // a scribble line inside the display

// 4 key boxes in a row
const keys = [
  [380, 190, 445, 255],
  [470, 190, 535, 255],
  [560, 190, 625, 255],
  [650, 190, 715, 255],
];
for (const [x1, y1, x2, y2] of keys) rect(x1, y1, x2, y2);

// digit marks inside the keys: 7, 8, 9, +
// "7": top bar + diagonal-ish vertical
hline(398, 428, 205, 3);
vline(208, 242, 424, 3);
// "8": two small stacked boxes
rect(486, 203, 519, 222, 2);
rect(486, 226, 519, 245, 2);
// "9": box + tail
rect(576, 203, 609, 226, 2);
vline(226, 245, 606, 3);
// "+": cross
hline(668, 700, 222, 3);
vline(204, 240, 684, 3);

// arrow from first key to the display
vline(130, 190, 412, 2);
// arrowhead
for (let t = 0; t < 8; t++) {
  set(412 - t, 138 + t);
  set(412 + t, 138 + t);
}

const raw = Buffer.alloc(H * (1 + W * 3));
for (let y = 0; y < H; y++) {
  raw[y * (1 + W * 3)] = 0;
  px.copy(raw, y * (1 + W * 3) + 1, y * W * 3, (y + 1) * W * 3);
}
const idat = deflateSync(raw);
const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
};
const ihdr = Buffer.alloc(13);
ihdr.writeUInt32BE(W, 0);
ihdr.writeUInt32BE(H, 4);
ihdr[8] = 8;
ihdr[9] = 2;
const png = Buffer.concat([
  Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
  chunk("IHDR", ihdr),
  chunk("IDAT", idat),
  chunk("IEND", Buffer.alloc(0)),
]);
writeFileSync("sketch.png", png);
console.log("wrote sketch.png", png.length, "bytes");

