export const EMPTY_GRAPH: AppGraph = {
  version: 1,
  screens: [{ id: "screen-1", name: "Untitled screen" }],
  components: [],
  initialState: {},
  entities: [
    {
      id: "tasks",
      name: "Task",
      fields: ["id", "title", "complete", "priority"],
    },
  ],
  events: [],
  actions: [],
  bindings: [],
  navigation: [],
  constraints: [],
  agentInstructions: [],
};

export function createId(prefix: string): string {
  const cryptoApi = globalThis.crypto;

  if (typeof cryptoApi?.randomUUID === "function") {
    return `${prefix}-${cryptoApi.randomUUID().slice(0, 8)}`;
  }

  if (typeof cryptoApi?.getRandomValues === "function") {
    const values = new Uint32Array(2);
    cryptoApi.getRandomValues(values);
    return `${prefix}-${Array.from(values, (value) =>
      value.toString(36),
    ).join("")}`;
  }

  return `${prefix}-${Date.now().toString(36)}${Math.random()
    .toString(36)
    .slice(2, 8)}`;
}

export function getStrokeBounds(stroke: InkStroke): Bounds {
  const xs = stroke.points.map((point) => point.x);
  const ys = stroke.points.map((point) => point.y);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return {
    x,
    y,
    width: Math.max(1, Math.max(...xs) - x),
    height: Math.max(1, Math.max(...ys) - y),
  };
}

export function guessComponentType(bounds: Bounds): ComponentType {
  const ratio = bounds.width / Math.max(bounds.height, 1);

  if (bounds.width < 64 && bounds.height < 64) return "Checkbox";
  if (ratio > 4.2) return "TextInput";
  if (ratio > 2.1 && bounds.height < 96) return "Button";
  if (bounds.height > 150 && bounds.height > bounds.width * 0.72) return "List";
  if (bounds.width > 230 && bounds.height > 130) return "Card";
  return "Button";
}

export function defaultProps(type: ComponentType): AppComponent["props"] {
  const defaults: Record<ComponentType, AppComponent["props"]> = {
    Text: { label: "Text", placeholder: "", options: [] },
    Button: { label: "Button", placeholder: "", options: [] },
    TextInput: {
      label: "",
      placeholder: "Type here…",
      options: [],
    },
    Textarea: {
      label: "",
      placeholder: "Write something…",
      options: [],
    },
    Checkbox: { label: "Option", placeholder: "", options: [] },
    Select: {
      label: "Choose…",
      placeholder: "",
      options: ["First", "Second", "Third"],
    },
    Image: { label: "Image", placeholder: "", options: [] },
    Card: { label: "", placeholder: "", options: [] },
    List: { label: "", placeholder: "", options: [] },
    Modal: { label: "Dialog", placeholder: "", options: [] },
    Tabs: {
      label: "",
      placeholder: "",
      options: ["Overview", "Details"],
    },
    Navbar: { label: "App", placeholder: "", options: [] },
  };

  return defaults[type];
}

export function isClosedShape(stroke: InkStroke): boolean {
  if (stroke.points.length < 8) return false;
  const bounds = getStrokeBounds(stroke);
  if (bounds.width < 28 || bounds.height < 22) return false;

  const first = stroke.points[0];
  const last = stroke.points[stroke.points.length - 1];
  const closingDistance = Math.hypot(last.x - first.x, last.y - first.y);
  return closingDistance < Math.max(34, Math.min(bounds.width, bounds.height) * 0.45);
}

export function hitTest(
  point: Point,
  component: AppComponent,
  padding = 0,
): boolean {
  const { x, y, width, height } = component.bounds;
  return (
    point.x >= x - padding &&
    point.x <= x + width + padding &&
    point.y >= y - padding &&
    point.y <= y + height + padding
  );
}

export function sanitizeComponentType(value: string): ComponentType {
  return COMPONENT_TYPES.includes(value as ComponentType)
    ? (value as ComponentType)
    : "Card";
}

export function sanitizeActionType(value: string): ActionType {
  const actions: ActionType[] = [
    "setState",
    "filter",
    "sort",
    "validate",
    "open",
    "close",
    "navigate",
    "fetch",
    "create",
    "update",
    "delete",
    "visibility",
    "custom",
  ];
  return actions.includes(value as ActionType)
    ? (value as ActionType)
    : "custom";
}

export function componentLabel(component: AppComponent): string {
  return (
    component.props.label ||
    component.props.placeholder ||
    component.type.replace(/([a-z])([A-Z])/g, "$1 $2")
  );
}

export function localHandler(
  source: AppComponent,
  target: AppComponent,
): Pick<
  BehaviorEdge,
  "instruction" | "triggerEvent" | "actionType" | "sourceData" | "predicate" | "handler" | "tests"
> {
  const targetKey = target.stateKey || target.id;

  if (
    (source.type === "TextInput" || source.type === "Textarea") &&
    target.type === "List"
  ) {
    return {
      instruction: "filter the list as I type",
      triggerEvent: "change",
      actionType: "filter",
      sourceData: target.dataSource || "tasks",
      predicate: "title contains the input value",
      handler: `set(${JSON.stringify(targetKey)}, String(event.value ?? ""));`,
      tests: [
        "filters records case-insensitively",
        "shows every record for an empty query",
      ],
    };
  }

  if (source.type === "Button" && target.type === "Modal") {
    return {
      instruction: "open the dialog",
      triggerEvent: "click",
      actionType: "open",
      sourceData: "",
      predicate: "",
      handler: `set(${JSON.stringify(openKey(target.id))}, true);`,
      tests: ["opens the target dialog on click"],
    };
  }

  return {
    instruction: `when ${componentLabel(source)} changes, update ${componentLabel(target)}`,
    triggerEvent:
      source.type === "TextInput" ||
      source.type === "Textarea" ||
      source.type === "Checkbox"
        ? "change"
        : "click",
    actionType: "setState",
    sourceData: "",
    predicate: "",
    handler: `set(${JSON.stringify(targetKey)}, event.value);`,
    tests: ["updates the target when the source event fires"],
  };
}

/** State key controlling whether an overlay component is visible. */
export function openKey(componentId: string): string {
  return `open:${componentId}`;
}

const COMPILED_BY = ["local", "codex", "claude", "copilot", "omp"] as const;

function asStringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.map((entry) => String(entry)) : [];
}

/**
 * Sanitizes an imported app.graph.json into a usable AppGraph. The graph is
 * the source of truth and is portable, so import must tolerate sloppy files:
 * unknown types fall back to defaults, dangling references are dropped,
 * duplicate ids are renamed, and events/actions are rebuilt from the
 * surviving bindings exactly the way processing builds them.
 */
export function restoreGraph(value: unknown): AppGraph {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("not an app graph object");
  }
  const raw = value as Record<string, unknown>;
  // A graph without a components array is a different kind of document (a
  // state dump, a settings file) — importing it must not wipe the canvas.
  if (!Array.isArray(raw.components)) {
    throw new Error("not an app graph object");
  }

  const num = (entry: unknown, fallback: number): number =>
    typeof entry === "number" && Number.isFinite(entry) ? entry : fallback;

  const components: AppComponent[] = [];
  const ids = new Set<string>();
  for (const entry of Array.isArray(raw.components) ? raw.components : []) {
    if (!entry || typeof entry !== "object") continue;
    const component = entry as Record<string, unknown>;
    const type = sanitizeComponentType(String(component.type ?? ""));
    const defaults = defaultProps(type);
    let id = String(component.id ?? "").replace(/[^a-zA-Z0-9_-]/g, "");
    if (!id) id = createId(type.toLowerCase());
    while (ids.has(id)) id = createId(type.toLowerCase());
    ids.add(id);

    const bounds = (
      component.bounds && typeof component.bounds === "object"
        ? component.bounds
        : {}
    ) as Record<string, unknown>;
    const props = (
      component.props && typeof component.props === "object"
        ? component.props
        : {}
    ) as Record<string, unknown>;

    components.push({
      id,
      type,
      bounds: {
        x: num(bounds.x, 0),
        y: num(bounds.y, 0),
        width: Math.max(1, num(bounds.width, 120)),
        height: Math.max(1, num(bounds.height, 48)),
      },
      props: {
        label: typeof props.label === "string" ? props.label : defaults.label,
        placeholder:
          typeof props.placeholder === "string"
            ? props.placeholder
            : defaults.placeholder,
        options: Array.isArray(props.options)
          ? props.options.map((option) => String(option))
          : defaults.options,
      },
      dataSource:
        typeof component.dataSource === "string" ? component.dataSource : "",
      stateKey: typeof component.stateKey === "string" ? component.stateKey : "",
      confidence: num(component.confidence, 1),
    });
  }

  const bindings: BehaviorEdge[] = [];
  for (const entry of Array.isArray(raw.bindings) ? raw.bindings : []) {
    if (!entry || typeof entry !== "object") continue;
    const edge = entry as Record<string, unknown>;
    const source = String(edge.source ?? "");
    const target = String(edge.target ?? "");
    if (!ids.has(source) || (target && !ids.has(target))) continue;
    const compiledBy = edge.compiledBy;
    bindings.push({
      id: String(edge.id || createId("edge")),
      source,
      target,
      instruction: typeof edge.instruction === "string" ? edge.instruction : "",
      triggerEvent:
        typeof edge.triggerEvent === "string" ? edge.triggerEvent : "click",
      actionType: sanitizeActionType(String(edge.actionType ?? "")),
      sourceData: typeof edge.sourceData === "string" ? edge.sourceData : "",
      predicate: typeof edge.predicate === "string" ? edge.predicate : "",
      handler: typeof edge.handler === "string" ? edge.handler : "",
      tests: asStringArray(edge.tests),
      compiledBy: (COMPILED_BY as readonly string[]).includes(
        String(compiledBy),
      )
        ? (compiledBy as BehaviorEdge["compiledBy"])
        : "local",
    });
  }

  const initialState: AppGraph["initialState"] = {};
  if (
    raw.initialState &&
    typeof raw.initialState === "object" &&
    !Array.isArray(raw.initialState)
  ) {
    for (const [key, entry] of Object.entries(
      raw.initialState as Record<string, unknown>,
    )) {
      if (
        typeof entry === "string" ||
        typeof entry === "number" ||
        typeof entry === "boolean" ||
        entry === null
      ) {
        initialState[key] = entry;
      }
    }
  }

  const screens = (Array.isArray(raw.screens) ? raw.screens : []).flatMap(
    (entry) => {
      if (!entry || typeof entry !== "object") return [];
      const screen = entry as Record<string, unknown>;
      return [
        {
          id: String(screen.id ?? createId("screen")),
          name: typeof screen.name === "string" ? screen.name : "Screen",
        },
      ];
    },
  );

  const entities = (Array.isArray(raw.entities) ? raw.entities : []).flatMap(
    (entry) => {
      if (!entry || typeof entry !== "object") return [];
      const entity = entry as Record<string, unknown>;
      return [
        {
          id: String(entity.id ?? createId("entity")),
          name: typeof entity.name === "string" ? entity.name : "Entity",
          fields: asStringArray(entity.fields),
        },
      ];
    },
  );

  const navigation = (
    Array.isArray(raw.navigation) ? raw.navigation : []
  ).flatMap((entry) => {
    if (!entry || typeof entry !== "object") return [];
    const link = entry as Record<string, unknown>;
    return [
      {
        from: String(link.from ?? ""),
        to: String(link.to ?? ""),
        condition: typeof link.condition === "string" ? link.condition : "",
      },
    ];
  });

  return {
    version: 1,
    screens: screens.length > 0 ? screens : EMPTY_GRAPH.screens.map((screen) => ({ ...screen })),
    components,
    initialState,
    entities: entities.length > 0 ? entities : EMPTY_GRAPH.entities.map((entity) => ({ ...entity, fields: [...entity.fields] })),
    events: bindings.map((edge) => ({
      id: `event-${edge.id}`,
      component: edge.source,
      event: edge.triggerEvent,
    })),
    actions: bindings.map((edge) => ({
      id: `action-${edge.id}`,
      type: edge.actionType,
      target: edge.target,
    })),
    bindings,
    navigation,
    constraints: asStringArray(raw.constraints),
    agentInstructions: asStringArray(raw.agentInstructions),
  };
}

