// Node strips the TypeScript types natively; app-graph.ts is erasable TS.
const { restoreGraph } = await import("../app/lib/app-graph.ts");

function component(id, type = "Button", overrides = {}) {
  return {
    id,
    type,
    bounds: { x: 10, y: 20, width: 100, height: 40 },
    props: { label: id, placeholder: "", options: [] },
    dataSource: "",
    stateKey: "",
    confidence: 1,
    ...overrides,
  };
}

function edge(id, source, target = "", overrides = {}) {
  return {
    id,
    source,
    target,
    instruction: `handle ${source}`,
    triggerEvent: "click",
    actionType: "setState",
    sourceData: "",
    predicate: "",
    handler: "set('x', 1);",
    tests: [],
    compiledBy: "omp",
    ...overrides,
  };
}

function graph(components = [], bindings = [], overrides = {}) {
  return {
    version: 1,
    screens: [{ id: "screen-1", name: "Untitled screen" }],
    components,
    initialState: {},
    entities: [{ id: "tasks", name: "Task", fields: ["id"] }],
    events: [],
    actions: [],
    bindings,
    navigation: [],
    constraints: [],
    agentInstructions: [],
    ...overrides,
  };
}

test("round-trips a clean exported graph", () => {
  const restored = restoreGraph(
    graph([component("a"), component("b")], [edge("e1", "a", "b")], {
      initialState: { display: "0" },
    }),
  );

