const finishStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  const resize = resizeRef.current;
  const drag = dragRef.current;
  const finished = draftRef.current;
  if (!resize && !drag && !finished) return;
  event.preventDefault();
  if (event.currentTarget.hasPointerCapture(event.pointerId)) {
    event.currentTarget.releasePointerCapture(event.pointerId);
  }
  if (resize) {
    // The size is already live on the component; just drop the gesture.
    resizeRef.current = null;
    return;
  }
  event.preventDefault();
  if (event.currentTarget.hasPointerCapture(event.pointerId)) {
    event.currentTarget.releasePointerCapture(event.pointerId);
  }
  if (drag) {
    dragRef.current = null;
    // A press-and-release without movement is a tap: select the component.
    if (!drag.moved) {
      setSelectedId(drag.id);
      setSidePanel("component");
      return;
    }
    // A release that lands on another component is a wiring arrow, not a
    // move: put the source back where it was and keep the ink.
    const end = drag.points[drag.points.length - 1];
    const over = [...graphRef.current.components].reverse().find(
      (component) => component.id !== drag.id && hitTest(end, component, 34),
    );
    if (over) {
      setGraph((current) => ({
        ...current,
        components: current.components.map((component) =>
          component.id === drag.id
            ? { ...component, bounds: { ...drag.bounds } }
            : component,
        ),
      }));
      setStrokes((current) => [
        ...current,
        { id: createId("stroke"), points: drag.points, processed: false },
      ]);
    }
    return;
  }
  if (!finished) return;
  draftRef.current = null;
  setDraftStroke(null);

  if (strokeLength(finished) < 12) {
    const tap = finished.points[0];
    const hit = [...graphRef.current.components]
      .reverse()
      .find((component) => hitTest(tap, component, 8));
    if (hit) {
      setSelectedId(hit.id);
      setSidePanel("component");
    } else {
      setSelectedId(null);
      setSidePanel(null);
    }
    return;
  }

  saveHistory();
  setStrokes((current) => [...current, finished]);
};

const cancelStroke = () => {
  draftRef.current = null;
  setDraftStroke(null);
  dragRef.current = null;
};

