.canvas-node {
  --node-x: 0px;
  --node-y: 0px;
  --node-width: 160px;
  --node-height: 52px;
  position: absolute;
  z-index: 2;
  left: var(--node-x);
  top: var(--node-y);
  width: var(--node-width);
  height: var(--node-height);
  min-width: 32px;
  min-height: 26px;
  animation: node-arrive 320ms cubic-bezier(0.2, 0.82, 0.2, 1) both;
}

/* In Draw mode the ink layer owns every pointer, so components sit inert
   underneath and the pen writes straight over them. */
.mode-draw .canvas-node {
  pointer-events: none;
}

/* A quiet dot marks components that already have logic attached. */
.mode-draw .canvas-node.is-wired::before {
  content: "";
  position: absolute;
  z-index: 3;
  right: -5px;
  top: -5px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--paper);
  border-radius: 50%;
  background: var(--violet);
}

.canvas-node.is-selected::after {
  content: "";
  position: absolute;
  inset: -7px;
  border: 2px solid var(--violet);
  border-radius: 11px;
  box-shadow: 0 0 0 3px rgba(93, 72, 219, 0.12);
}

.node-type-tag {
  position: absolute;
  z-index: 3;
  left: 7px;
  top: -21px;
  padding: 3px 6px;
  border-radius: 4px;
  background: var(--ink);
  color: white;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(3px);
  transition:
    opacity 120ms ease,
    transform 120ms ease;
}

.canvas-node.is-selected .node-type-tag {
  opacity: 1;
  transform: translateY(0);
}

