// keyPlus is selected? re-select (undo may have kept selection)
const sel = await page.$eval('.canvas-node.is-selected', el => el.dataset.componentId).catch(() => null);
if (sel !== 'keyPlus') {
  await page.mouse.move(684, 226);
  await page.mouse.down();
  await new Promise(r => setTimeout(r, 50));
  await page.mouse.up();
  await new Promise(r => setTimeout(r, 300));
}
// Drag handle far inward: corner (718,262) by (-200,-200) → should clamp to 24x24
await page.mouse.move(718, 262);
await page.mouse.down();
for (let i = 1; i <= 8; i++) {
  await page.mouse.move(718 - 200 * (i / 8), 262 - 200 * (i / 8));
  await new Promise(r => setTimeout(r, 16));
}
await page.mouse.up();
await new Promise(r => setTimeout(r, 300));
const size = await page.$eval('[data-component-id="keyPlus"]', el => ({ w: el.style.getPropertyValue('--node-width'), h: el.style.getPropertyValue('--node-height') }));
// undo back
await page.keyboard.down('Meta');
await page.keyboard.press('z');
await page.keyboard.up('Meta');
await new Promise(r => setTimeout(r, 300));
return { size };
